                <span
                  className={`ml-auto text-xs ${
                    bulkMessage.ok ? "text-emerald-300" : "text-rose-300"
                  }`}
                >
                  {bulkMessage.text}
                </span>
              )}
            </div>
          )}

          {/* Posts list */}
