              <p className="px-3 py-2 text-xs text-[var(--ink-4)]">
                {posts.length === 0 ? t.emptyAll : t.emptyFiltered}
              </p>
            )}
            {filtered.length > 0 && (
              <div className="overflow-x-auto">
