                        <td className="px-3 py-2">
                          <span className="inline-flex items-center rounded-md bg-[var(--bg-3)] px-1.5 py-0.5 text-[10px] uppercase tracking-wide text-[var(--ink-3)]">
                            {post.locale}
                          </span>
                        </td>
                        <td className="px-3 py-2">
