                            <option value="draft">{t.rowDraft}</option>
                            <option value="published">{t.rowPublished}</option>
                            <option value="archived">{t.rowArchived}</option>
                          </select>
                        </td>
                        <td className="px-3 py-2 text-[var(--ink-3)]">
                          {post.authorUsername ?? `#${post.authorId}`}
                        </td>
