interface CopyShape {
  justNow: string;
  minutesAgo: (n: number) => string;
  hoursAgo: (n: number) => string;
  daysAgo: (n: number) => string;
  dateLocale: string;
  title: string;
  subtitle: string;
  recentActivity: string;
  loading: string;
  noActivity: string;
}

const COPY: CopyMap<CopyShape> = {
  en: {
    justNow: "just now",
    minutesAgo: (n) => `${n}m ago`,
    hoursAgo: (n) => `${n}h ago`,
    daysAgo: (n) => `${n}d ago`,
