"use client";

import { useEffect, useState } from "react";
import { useI18n } from "@/lib/i18n/context";
import { resolveCopy, type CopyMap } from "@/lib/i18n/translations";

interface CopyShape {
  dateLocale: string;
}

const COPY: CopyMap<CopyShape> = {
  en: { dateLocale: "en" },
  ru: { dateLocale: "ru-RU" },
  de: { dateLocale: "de-DE" },
  fr: { dateLocale: "fr-FR" },
  es: { dateLocale: "es-ES" },
};

interface AuditEntry {
  id: number;
  action: string;
  resourceType: string;
  resourceId: number;
  payload: string | null;
  createdAt: string;
}

interface AuditPanelProps {
  open: boolean;
  onClose: () => void;
}

export function AuditPanel({ open, onClose }: AuditPanelProps) {
  const { locale } = useI18n();
  const t = resolveCopy(COPY, locale);
  const [entries, setEntries] = useState<AuditEntry[]>([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (!open) return;
    setLoading(true);
    fetch("/api/audit")
      .then((r) => (r.ok ? r.json() : { entries: [] }))
      .then((data) => setEntries(Array.isArray(data?.entries) ? data.entries : []))
      .catch(() => setEntries([]))
      .finally(() => setLoading(false));
  }, [open]);

  if (!open) return null;

  const formatDate = (iso: string) =>
    new Date(iso).toLocaleString(t.dateLocale, {
      month: "short",
      day: "numeric",
      hour: "2-digit",
      minute: "2-digit",
    });

  const summarize = (e: AuditEntry): string => {
    if (!e.payload) return `#${e.resourceId}`;
    try {
      const obj = JSON.parse(e.payload) as Record<string, unknown>;
      const keys = Object.keys(obj).filter((k) => obj[k] !== undefined);
      if (keys.length === 0) return `#${e.resourceId}`;
      const head = keys.slice(0, 3).join(", ");
      return `#${e.resourceId} · ${head}`;
    } catch {
      return `#${e.resourceId}`;
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4">
      <div className="w-full max-w-xl rounded-2xl border border-[var(--line)] bg-[var(--bg-2)] p-6 shadow-2xl">
        <div className="mb-4 flex items-center justify-between">
          <h2 className="text-lg font-semibold text-[var(--ink)]">Recent activity</h2>
          <button
            onClick={onClose}
            className="rounded-md p-1 text-[var(--ink-3)] hover:bg-[var(--line-2)] hover:text-[var(--ink)]"
            aria-label="Close"
          >
            <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        <div className="max-h-[60vh] overflow-y-auto">
          {loading ? (
            <div className="py-12 text-center text-sm text-[var(--ink-4)]">Loading…</div>
          ) : entries.length === 0 ? (
            <div className="py-12 text-center text-sm text-[var(--ink-4)]">No activity yet.</div>
          ) : (
            <ul className="space-y-1.5">
              {entries.map((e) => (
                <li
                  key={e.id}
                  className="flex items-center justify-between gap-3 rounded-md border border-[var(--line)] bg-[var(--bg)] px-3 py-2 text-xs"
                >
                  <div className="flex min-w-0 flex-1 items-center gap-2">
                    <span
                      className={
                        "shrink-0 rounded px-1.5 py-0.5 text-[10px] font-semibold uppercase " +
                        (e.action === "create"
                          ? "bg-emerald-500/15 text-emerald-500"
                          : e.action === "delete"
                          ? "bg-rose-500/15 text-rose-500"
                          : "bg-sky-400/15 text-sky-400")
                      }
                    >
                      {e.action}
                    </span>
                    <span className="shrink-0 text-[var(--ink-3)]">{e.resourceType}</span>
                    <span className="truncate text-[var(--ink)]">{summarize(e)}</span>
                  </div>
                  <span className="shrink-0 text-[var(--ink-4)]">{formatDate(e.createdAt)}</span>
                </li>
              ))}
            </ul>
          )}
        </div>
      </div>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import { Button } from "@/components/ui/button";
import { PlatformInstructions } from "@/components/platform-instructions";
import type { CalendarLink, CalendarEvent, SyncLogEntry } from "@/lib/types";

interface CalendarSyncProps {
  propertyId: number;
  propertyName: string;
}

/* ────────────────────────────────── helpers ────────────────────────────── */

function addDays(date: Date, n: number) {
  const d = new Date(date);
  d.setDate(d.getDate() + n);
  return d;
}
function fmtDate(d: Date) {
  return d.toISOString().substring(0, 10);
}
function parseYMD(s: string) {
  const [y, m, d] = s.split("-").map(Number);
  return new Date(y, m - 1, d);
}
const MONTH_NAMES = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
const DAY_NAMES = ["Mo", "Tu", "We", "Th", "Fr", "Sa", "Su"];

/* ────────────────────────────── calendar grid ─────────────────────────── */

interface CalendarDay {
  date: Date;
  dateStr: string;
  isToday: boolean;
  isCurrentMonth: boolean;
  airbnb: boolean;   // booked on airbnb
  booking: boolean;  // booked on booking
  bufferDay: boolean; // buffer day (our addition)
}

function buildCalendarMonths(
  year: number,
  month: number, // 0-indexed
  monthCount: number,
  events: CalendarEvent[],
  links: CalendarLink[],
) {
  // Build a set of booked date strings per platform
  const airbnbDates = new Set<string>();
  const bookingDates = new Set<string>();

  for (const ev of events) {
    const start = parseYMD(ev.startDate);
    const end = parseYMD(ev.endDate);
    const set = ev.platform === "booking" ? bookingDates : airbnbDates;
    for (let d = new Date(start); d < end; d = addDays(d, 1)) {
      set.add(fmtDate(d));
    }
  }

  // Build buffer dates — dates that are NOT in any booking but would be blocked by buffer
  const bufferDates = new Set<string>();
  const airbnbLink = links.find((l) => l.platform === "airbnb");
  const bookingLink = links.find((l) => l.platform === "booking");

  for (const ev of events) {
    const start = parseYMD(ev.startDate);
    const end = parseYMD(ev.endDate);
    const link = ev.platform === "airbnb" ? airbnbLink : bookingLink;
    const bBefore = link?.bufferBefore ?? 0;
    const bAfter = link?.bufferAfter ?? 0;

    for (let i = 1; i <= bBefore; i++) {
      const d = fmtDate(addDays(start, -i));
      if (!airbnbDates.has(d) && !bookingDates.has(d)) bufferDates.add(d);
    }
    for (let i = 0; i < bAfter; i++) {
      const d = fmtDate(addDays(end, i));
      if (!airbnbDates.has(d) && !bookingDates.has(d)) bufferDates.add(d);
    }
  }

  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const todayStr = fmtDate(today);

  const months: { year: number; month: number; label: string; days: CalendarDay[] }[] = [];

  for (let m = 0; m < monthCount; m++) {
    const mDate = new Date(year, month + m, 1);
    const mYear = mDate.getFullYear();
    const mMonth = mDate.getMonth();
    const label = `${MONTH_NAMES[mMonth]} ${mYear}`;

    // First day of month — shift to Monday-start (0=Mon..6=Sun)
    const firstDow = (mDate.getDay() + 6) % 7;
    const daysInMonth = new Date(mYear, mMonth + 1, 0).getDate();

    const days: CalendarDay[] = [];

    // Leading empty days
    for (let i = 0; i < firstDow; i++) {
      const d = addDays(mDate, -(firstDow - i));
      const ds = fmtDate(d);
      days.push({
        date: d, dateStr: ds, isToday: ds === todayStr, isCurrentMonth: false,
        airbnb: airbnbDates.has(ds), booking: bookingDates.has(ds), bufferDay: bufferDates.has(ds),
      });
    }

    for (let i = 1; i <= daysInMonth; i++) {
      const d = new Date(mYear, mMonth, i);
      const ds = fmtDate(d);
      days.push({
        date: d, dateStr: ds, isToday: ds === todayStr, isCurrentMonth: true,
        airbnb: airbnbDates.has(ds), booking: bookingDates.has(ds), bufferDay: bufferDates.has(ds),
      });
    }

    // Trailing to fill last week
    while (days.length % 7 !== 0) {
      const d = addDays(new Date(mYear, mMonth, daysInMonth), days.length - firstDow - daysInMonth + 1);
      const ds = fmtDate(d);
      days.push({
        date: d, dateStr: ds, isToday: ds === todayStr, isCurrentMonth: false,
        airbnb: airbnbDates.has(ds), booking: bookingDates.has(ds), bufferDay: bufferDates.has(ds),
      });
    }

    months.push({ year: mYear, month: mMonth, label, days });
  }

  return months;
}

