"use client";

import { createContext, useContext, useState, useEffect, useCallback } from "react";
import { resolveCopy, translations, type Locale, type TranslationKey } from "./translations";
import {
  isLocale,
  readLocaleCookieFromDocument,
  writeLocaleCookieToDocument,
} from "./cookie";

interface I18nContextType {
  locale: Locale;
  setLocale: (locale: Locale) => void;
  t: (key: TranslationKey, params?: Record<string, string | number>) => string;
}

const I18nContext = createContext<I18nContextType>({
  locale: "en",
  setLocale: () => {},
  t: (key) => translations[key]?.en || key,
});

const LEGACY_LOCALSTORAGE_KEY = "rent-tool-locale";

function isSecureContext(): boolean {
  if (typeof window === "undefined") return true;
  return window.location.protocol === "https:";
}

export function I18nProvider({
  children,
  initialLocale,
}: {
  children: React.ReactNode;
  // Server-resolved locale (URL prefix → header → cookie → "en"). Passing
  // it in means the first client paint already matches what the server
  // rendered, no hydration flash from a default locale.
  initialLocale?: Locale;
}) {
  const [locale, setLocaleState] = useState<Locale>(initialLocale ?? "en");

  useEffect(() => {
    // The server already passed in the URL-resolved locale via
    // initialLocale. We still run the cookie/legacy migration so a stale
    // localStorage entry from before the cookie migration gets cleaned
    // up — but we never *override* the URL-resolved locale. URL beats
    // cookie always; the cookie is now only a soft preference for
    // the next request.
    if (initialLocale) return;

    const fromCookie = readLocaleCookieFromDocument(
      typeof document !== "undefined" ? document : null
    );
    if (fromCookie) {
      setLocaleState(fromCookie);
      return;
    }

    try {
      const legacy = localStorage.getItem(LEGACY_LOCALSTORAGE_KEY);
      if (isLocale(legacy)) {
        setLocaleState(legacy);
        writeLocaleCookieToDocument(
          typeof document !== "undefined" ? document : null,
          legacy,
          { secure: isSecureContext() }
        );
        localStorage.removeItem(LEGACY_LOCALSTORAGE_KEY);
      }
    } catch {
      // localStorage unavailable (private mode, SSR, etc.) — ignore
    }
  }, [initialLocale]);

  const setLocale = useCallback((l: Locale) => {
    setLocaleState(l);
    writeLocaleCookieToDocument(
      typeof document !== "undefined" ? document : null,
      l,
      { secure: isSecureContext() }
    );
  }, []);

  const t = useCallback(
    (key: TranslationKey, params?: Record<string, string | number>) => {
      const entry = translations[key];
      if (!entry) return key;
      // Not every key carries every locale (hr is being filled in
      // gradually); anything missing walks LOCALE_FALLBACK (hr -> de -> en).
      let text: string = resolveCopy<string>(entry, locale);
      if (params) {
        for (const [k, v] of Object.entries(params)) {
          text = text.replace(`{${k}}`, String(v));
        }
      }
      return text;
    },
    [locale]
  );

  return (
    <I18nContext.Provider value={{ locale, setLocale, t }}>
      {children}
    </I18nContext.Provider>
  );
}

export function useI18n() {
  return useContext(I18nContext);
}

import type { Locale, CopyMap } from "@/lib/i18n/translations";

/**
 * Mapping from our internal locale code (`Locale` union, e.g. "en", "ru")
 * to the format third-party APIs expect. These are exhaustive lookup
 * tables typed as `CopyMap<string>`, so adding a new value to the
 * Locale union forces a compile error here until the new mapping is
 * filled in. No more `locale === "ru" ? "ru_RU" : "en_US"` ternaries
 * scattered across the codebase silently falling back to English.
 */

/**
 * Open Graph locale tag (`og:locale` meta property). Format is
 * `<language>_<COUNTRY>` per the OG spec. Picking a country code is
 * unavoidable — `en_US` / `en_GB` / `en_AU` are all valid; we pick the
 * dominant variant for each language.
 */
export const OG_LOCALE: Record<Locale, string> = {
  en: "en_US",
  ru: "ru_RU",
  de: "de_DE",
  fr: "fr_FR",
  es: "es_ES",
  hr: "hr_HR",
};

export function toOgLocale(locale: Locale): string {
  return OG_LOCALE[locale];
}

/**
 * BCP-47 language tag for `Intl` APIs (toLocaleDateString, Intl.DateTimeFormat,
 * Intl.NumberFormat, etc.). Format is `<language>-<REGION>`. EN uses
 * `en-GB` because we're EU-targeting day-month order; RU uses `ru-RU`.
 */
export const BCP47_TAG: Record<Locale, string> = {
  en: "en-GB",
  ru: "ru-RU",
  de: "de-DE",
  fr: "fr-FR",
  es: "es-ES",
  hr: "hr-HR",
};

export function toBcp47(locale: Locale): string {
  return BCP47_TAG[locale];
}

/**
 * iCal (.ics) parser and generator.
 * No external dependencies — iCal for blocked dates is a simple text format.
 */

import { normalizeStoredCalendarBuffer } from "@/lib/calendar-link-input";

export interface ICalEvent {
  uid: string;
  summary: string;
  startDate: string; // YYYY-MM-DD
  endDate: string;   // YYYY-MM-DD
}

/**
 * Parse an iCal (.ics) string into a list of events.
 * Handles both DATE and DATE-TIME formats.
 */
export function parseICal(icalText: string): ICalEvent[] {
  const events: ICalEvent[] = [];
  const blocks = icalText.split("BEGIN:VEVENT");

  for (let i = 1; i < blocks.length; i++) {
    const block = blocks[i].split("END:VEVENT")[0];
    if (!block) continue;

    // Unfold lines (iCal spec: lines starting with space/tab are continuations)
    const unfolded = block.replace(/\r?\n[ \t]/g, "");
    const lines = unfolded.split(/\r?\n/);

    let uid = "";
    let summary = "";
    let startDate = "";
    let endDate = "";

    for (const line of lines) {
      const trimmed = line.trim();

      if (trimmed.startsWith("UID:")) {
        uid = trimmed.substring(4).trim();
      } else if (trimmed.startsWith("SUMMARY:")) {
        summary = trimmed.substring(8).trim();
      } else if (trimmed.startsWith("DTSTART")) {
        startDate = extractDate(trimmed);
      } else if (trimmed.startsWith("DTEND")) {
        endDate = extractDate(trimmed);
      }
    }

    if (startDate) {
      // If no end date, assume 1-day event
      if (!endDate) endDate = startDate;
      if (!uid) uid = `parsed-${startDate}-${i}`;

      events.push({ uid, summary, startDate, endDate });
    }
  }

  return events;
}

/**
 * Extract a YYYY-MM-DD date from an iCal date line.
 * Handles: DTSTART;VALUE=DATE:20240115
 *          DTSTART:20240115T140000Z
 *          DTSTART;TZID=Europe/Berlin:20240115T140000
 */
function extractDate(line: string): string {
  const colonIdx = line.indexOf(":");
  if (colonIdx === -1) return "";

  const value = line.substring(colonIdx + 1).trim();
  // Take first 8 chars (YYYYMMDD) and format
  const raw = value.replace(/[^0-9]/g, "").substring(0, 8);
  if (raw.length < 8) return "";

  return `${raw.substring(0, 4)}-${raw.substring(4, 6)}-${raw.substring(6, 8)}`;
}

/**
 * Add days to a YYYY-MM-DD date string.
 */
export function addDays(dateStr: string, days: number): string {
  const d = new Date(dateStr + "T12:00:00Z"); // noon UTC to avoid DST issues
  d.setUTCDate(d.getUTCDate() + days);
  return d.toISOString().substring(0, 10);
}

/**
 * Generate an iCal (.ics) string from a list of events.
 * Used to create enhanced feeds with buffer days.
 */
export function generateICal(
  events: ICalEvent[],
  calendarName: string = "RentTools Sync"
): string {
  const lines: string[] = [
    "BEGIN:VCALENDAR",
    "VERSION:2.0",
    "PRODID:-//RentTool//CalendarSync//EN",
    `X-WR-CALNAME:${calendarName}`,
    "METHOD:PUBLISH",
  ];

  // Some platforms (older Booking.com importers in particular) reject a
  // VCALENDAR with zero VEVENTs. Emit a single far-past placeholder so the
  // feed always validates while the property has no real bookings to share.
  const eventsToEmit: ICalEvent[] = events.length > 0 ? events : [{
    uid: "renttools-placeholder",
    summary: "RentTools placeholder",
    startDate: "1970-01-01",
    endDate: "1970-01-02",
  }];

  for (const event of eventsToEmit) {
    const dtstart = event.startDate.replace(/-/g, "");
    const dtend = event.endDate.replace(/-/g, "");
    // Sanitize UID and summary for iCal compatibility (ASCII only, no special chars)
    const uid = event.uid.replace(/[^a-zA-Z0-9@._-]/g, "_");
    const summary = event.summary.replace(/[^\x20-\x7E]/g, "");

    lines.push("BEGIN:VEVENT");
    lines.push(`UID:${uid}`);
    lines.push(`DTSTART;VALUE=DATE:${dtstart}`);
    lines.push(`DTEND;VALUE=DATE:${dtend}`);
    lines.push(`SUMMARY:${summary}`);
    lines.push(`DTSTAMP:${formatNowUTC()}`);
    lines.push("END:VEVENT");
  }

  lines.push("END:VCALENDAR");
  return lines.join("\r\n");
}

function formatNowUTC(): string {
  const now = new Date();
  return now.toISOString().replace(/[-:]/g, "").replace(/\.\d+Z$/, "Z");
}

/**
 * Given events from one platform, generate blocked events with buffer days
 * for import into the other platform.
 */
export function generateBufferedEvents(
  events: ICalEvent[],
  bufferBefore: number,
  bufferAfter: number,
  sourcePlatform: string,
  _minNights: number = 3 // kept for API compat, not used in feed (platforms handle their own min-nights)
): ICalEvent[] {
  if (events.length === 0) return [];

  const safeBufferBefore = normalizeStoredCalendarBuffer(bufferBefore);
  const safeBufferAfter = normalizeStoredCalendarBuffer(bufferAfter);

  // Only export cleaning buffer days to platforms, NOT unbookable gap days.
  // Platforms handle their own min-night rules.
  // endDate is iCal exclusive (checkout day). bufferAfter counts calendar
  // days starting with that checkout date. Therefore 0 keeps checkout open,
  // while 1 closes exactly checkout day (exclusive end = checkout + 1).
  const buffered = events.map((event) => ({
    start: addDays(event.startDate, -safeBufferBefore),
    end: addDays(event.endDate, safeBufferAfter),
    count: 1,
  }));

  // Sort by start date
  buffered.sort((a, b) => a.start.localeCompare(b.start));

  // Merge overlapping/adjacent ranges so buffers between close bookings don't double up
  const merged: { start: string; end: string; count: number }[] = [];
  for (const b of buffered) {
    const last = merged[merged.length - 1];
    if (last && b.start <= last.end) {
      if (b.end > last.end) last.end = b.end;
      last.count++;
    } else {
      merged.push({ ...b, count: 1 });
    }
  }

  const label = `Blocked (${sourcePlatform}${safeBufferBefore || safeBufferAfter ? " +buffer" : ""})`;
  return merged.map((m, i) => ({
    uid: `renttool-${sourcePlatform}-${m.start}-${m.end}-${i}`,
    summary: label,
    startDate: m.start,
    endDate: m.end,
  }));
}

/**
 * Generate buffer-only events (cleaning days) around same-platform bookings.
 * Does NOT include the booking dates themselves — only the cleaning buffer days.
 */
export function generateBufferOnlyEvents(
  events: ICalEvent[],
  bufferBefore: number,
  bufferAfter: number,
  label: string = "Blocked (cleaning)"
): ICalEvent[] {
  if (events.length === 0) return [];

  const safeBufferBefore = normalizeStoredCalendarBuffer(bufferBefore);
  const safeBufferAfter = normalizeStoredCalendarBuffer(bufferAfter);

  const result: ICalEvent[] = [];

  for (const event of events) {
    // Buffer before: days before the booking starts
    if (safeBufferBefore > 0) {
      const start = addDays(event.startDate, -safeBufferBefore);
      result.push({
        uid: `renttool-buffer-before-${event.startDate}-${event.uid}`,
        summary: label,
        startDate: start,
        endDate: event.startDate, // exclusive end = up to (not including) booking start
      });
    }

    // Buffer after starts on checkout day. With a value of 1, that exact
    // calendar day is closed; with 0, same-day turnover stays possible.
    if (safeBufferAfter > 0) {
      const start = event.endDate;
      const end = addDays(event.endDate, safeBufferAfter);
      result.push({
        uid: `renttool-buffer-after-${event.endDate}-${event.uid}`,
        summary: label,
        startDate: start,
        endDate: end,
      });
    }
  }

  return result;
}

const ISO_DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
const DAY_MS = 24 * 60 * 60 * 1000;

export const DEFAULT_PROPERTY_TIME_ZONE = "Europe/Zagreb";
export const OWNER_CALENDAR_PAST_MONTHS = 6;

export interface OwnerCalendarWindow {
  today: string;
  visibleFrom: string;
  /** Last night that can be occupied / last check-in date. */
  visibleUntil: string;
  /** Checkout is exclusive, so it may be one day after visibleUntil. */
  checkoutUntil: string;
  timeZone: string;
}

function assertIsoDate(value: string): void {
  if (!ISO_DATE_RE.test(value)) throw new Error(`Invalid ISO date: ${value}`);
  const parsed = new Date(`${value}T00:00:00.000Z`);
  if (Number.isNaN(parsed.getTime()) || parsed.toISOString().slice(0, 10) !== value) {
    throw new Error(`Invalid ISO date: ${value}`);
  }
}

export function addCalendarDays(date: string, days: number): string {
  assertIsoDate(date);
  if (!Number.isInteger(days)) throw new Error("Calendar day offset must be an integer");
  const value = new Date(`${date}T00:00:00.000Z`);
  value.setUTCDate(value.getUTCDate() + days);
  return value.toISOString().slice(0, 10);
}

export function dateInTimeZone(
  now: Date,
  timeZone: string = DEFAULT_PROPERTY_TIME_ZONE,
): string {
  if (Number.isNaN(now.getTime())) throw new Error("Invalid current time");
  const parts = new Intl.DateTimeFormat("en-CA", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(now);
  const part = (type: Intl.DateTimeFormatPartTypes) =>
    parts.find((entry) => entry.type === type)?.value;
  const year = part("year");
  const month = part("month");
  const day = part("day");
  if (!year || !month || !day) throw new Error(`Could not resolve date in ${timeZone}`);
  return `${year}-${month}-${day}`;
}

function shiftMonthStart(date: string, monthOffset: number): string {
  assertIsoDate(date);
  const [year, month] = date.split("-").map(Number);
  const shifted = new Date(Date.UTC(year, month - 1 + monthOffset, 1));
  return shifted.toISOString().slice(0, 10);
}

export function getOwnerCalendarWindow(options: {
  bookingWindowDays: number;
  timeZone?: string;
  now?: Date;
  pastMonths?: number;
}): OwnerCalendarWindow {
  const bookingWindowDays = options.bookingWindowDays;
  if (!Number.isInteger(bookingWindowDays) || bookingWindowDays < 1) {
    throw new Error("bookingWindowDays must be a positive integer");
  }
  const pastMonths = options.pastMonths ?? OWNER_CALENDAR_PAST_MONTHS;
  if (!Number.isInteger(pastMonths) || pastMonths < 0) {
    throw new Error("pastMonths must be a non-negative integer");
  }
  const timeZone = options.timeZone || DEFAULT_PROPERTY_TIME_ZONE;
  const today = dateInTimeZone(options.now ?? new Date(), timeZone);
  const visibleUntil = addCalendarDays(today, bookingWindowDays);
  return {
    today,
    visibleFrom: shiftMonthStart(today, -pastMonths),
    visibleUntil,
    checkoutUntil: addCalendarDays(visibleUntil, 1),
    timeZone,
  };
}

export function ownerCalendarMonthStarts(window: OwnerCalendarWindow): string[] {
  const result: string[] = [];
  let cursor = window.visibleFrom.slice(0, 7) + "-01";
  const finalMonth = window.visibleUntil.slice(0, 7) + "-01";
  while (cursor <= finalMonth) {
    result.push(cursor);
    cursor = shiftMonthStart(cursor, 1);
  }
  return result;
}

export function isOwnerCalendarOccupancyDate(
  date: string,
  window: OwnerCalendarWindow,
): boolean {
  assertIsoDate(date);
  return date >= window.visibleFrom && date <= window.visibleUntil;
}

export function isReservationRangeInOwnerCalendarWindow(
  checkIn: string,
  checkOut: string,
  window: OwnerCalendarWindow,
): boolean {
  assertIsoDate(checkIn);
  assertIsoDate(checkOut);
  return (
    checkIn >= window.visibleFrom &&
    checkIn <= window.visibleUntil &&
    checkOut > checkIn &&
    checkOut <= window.checkoutUntil
  );
}

